public sealed class HallPagedText:UserControl {
 Label body,counter;Panel footer;VNButton previous,next;string text="";int at;bool layingOut;List<string> pages=new List<string>();
 public HallPagedText(){BackColor=Color.FromArgb(25,53,50);body=new Label{Dock=DockStyle.Fill,ForeColor=GuildChrome.Ivory,Font=GameTheme.Body(12),Padding=new Padding(2,0,2,0),UseMnemonic=false};footer=new Panel{Dock=DockStyle.Bottom,Height=18,Visible=false};previous=new VNButton{Icon="prev",Dock=DockStyle.Left,Width=32,AccessibleName="上一页文本"};next=new VNButton{Icon="next",Dock=DockStyle.Right,Width=32,AccessibleName="下一页文本"};counter=new Label{Dock=DockStyle.Fill,Font=GameTheme.Body(9),ForeColor=GuildChrome.Muted,TextAlign=ContentAlignment.MiddleCenter};footer.Controls.Add(counter);footer.Controls.Add(previous);footer.Controls.Add(next);Controls.Add(body);Controls.Add(footer);previous.Click+=(s,e)=>{at=Math.Max(0,at-1);ShowPage();};next.Click+=(s,e)=>{at=Math.Min(pages.Count-1,at+1);ShowPage();};Resize+=(s,e)=>Paginate();}
 public string LiveContent{set{if(text==value)return;int previous=at;text=value??"";Paginate();at=Math.Min(previous,pages.Count-1);ShowPage();}}
 public string Content{get{return text;}set{if(text==value)return;text=value??"";at=0;Paginate();}}
 protected override void OnFontChanged(EventArgs e){base.OnFontChanged(e);if(body!=null){body.Font=Font;Paginate();}}
 void Paginate(){if(layingOut||Width<15||Height<15)return;layingOut=true;try{int w=Math.Max(20,Width-12);bool needs=TextRenderer.MeasureText(text,body.Font,new Size(w,Int32.MaxValue),TextFormatFlags.WordBreak).Height>Height-4;footer.Visible=needs;int h=Math.Max(8,Height-4-(needs?18:0));pages.Clear();string remaining=text;while(remaining.Length>0){int lo=1,hi=remaining.Length;while(lo<hi){int mid=(lo+hi+1)/2;if(TextRenderer.MeasureText(remaining.Substring(0,mid),body.Font,new Size(w,Int32.MaxValue),TextFormatFlags.WordBreak).Height<=h)lo=mid;else hi=mid-1;}if(lo<remaining.Length){int line=remaining.LastIndexOf('\n',lo-1,lo);if(line>lo/2)lo=line+1;else{int space=remaining.LastIndexOf(' ',lo-1,lo);if(space>lo/2)lo=space+1;}}pages.Add(remaining.Substring(0,lo));remaining=remaining.Substring(lo);}if(pages.Count==0)pages.Add("");at=Math.Min(at,pages.Count-1);ShowPage();}finally{layingOut=false;}}
 void ShowPage(){if(pages.Count==0)return;body.Text=pages[at];previous.Enabled=at>0;next.Enabled=at+1<pages.Count;counter.Text=(at+1)+" / "+pages.Count;}
}
