 TableLayoutPanel HallRows(Control parent,int count){var table=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=count,BackColor=Color.FromArgb(25,53,55)};table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<count;i++)table.RowStyles.Add(new RowStyle(SizeType.Percent,100f/count));parent.Controls.Add(table);return table;}
