 void BuildHallGuidance(Panel parent,TavernHallState s){hallRefreshAudio=null;hallSaveStudy=null;var heading=new OutlinedLabel{Text="英语指导 · 选择词库",Font=GameTheme.Body(15),ForeColor=GameTheme.Gold};var progress=new HallPagedText{Font=GameTheme.Body(11)};parent.Controls.Add(heading);parent.Controls.Add(progress);var choices=new List<VNButton>();Action refresh=()=>{string mode=ExpeditionVocabulary.Profile(save.rogue).mode;progress.Content=VocabularyProgressText(mode).Replace(" · 学习中","\n学习中");foreach(var button in choices){button.Active=button.AccessibleName==mode;button.Text=(button.Active?"●  ":"○  ")+button.AccessibleName;button.Invalidate();}};foreach(string name in new[]{"四级词汇","六级词汇","四六级混合"}){string selected=name;var button=HallAction(name,()=>{var profile=ExpeditionVocabulary.Profile(save.rogue);if(profile.mode!=selected){profile.mode=selected;s.wordQuestion=null;s.guidanceFeedback=null;}refresh();Persist();});button.Dock=DockStyle.None;button.AccessibleName=name;choices.Add(button);parent.Controls.Add(button);}var start=PartyButton("开始背单词",()=>{while(parent.Controls.Count>0)parent.Controls[0].Dispose();BuildHallGuidancePractice(parent,s);},200,42);parent.Controls.Add(start);Action layout=()=>{int width=Math.Max(80,parent.ClientSize.Width-16);bool compact=parent.ClientSize.Height<350;heading.Bounds=new Rectangle(8,4,width,30);progress.Bounds=new Rectangle(8,compact?36:48,width,compact?70:68);for(int i=0;i<choices.Count;i++)choices[i].Bounds=new Rectangle(8,(compact?112:128)+i*(compact?36:50),width,compact?32:42);start.Bounds=new Rectangle(8,compact?226:290,width,compact?32:42);};parent.Resize+=(o,e)=>{if(!heading.IsDisposed)layout();};refresh();layout();}
 void BuildHallGuidancePractice(Panel parent,TavernHallState s){hallRefreshAudio=null;hallSaveStudy=null;string mode=ExpeditionVocabulary.Profile(save.rogue).mode;Action refresh=null,layout=null;Action<int> answer=null;
  var progress=new HallPagedText{Font=GameTheme.Body(11)};var title=new OutlinedLabel{Font=GameTheme.Body(14),ForeColor=GameTheme.Gold};var status=new OutlinedLabel{Font=GameTheme.Body(12),ForeColor=GuildChrome.Ivory};var word=new OutlinedLabel{Font=GameTheme.Latin(21),ForeColor=GuildChrome.Ivory};var pronunciation=new Label{Font=new Font("Segoe UI",12),ForeColor=GuildChrome.Muted,BackColor=parent.BackColor,AutoSize=false};var meaning=new HallPagedText{Font=GameTheme.Body(14)};var input=new TextBox{BackColor=Color.FromArgb(34,68,65),ForeColor=TextColor,Font=GameTheme.Latin(15),AccessibleName="输入英文拼写"};var hear=new RogueIcon{Kind="speaker",AccessibleName="朗读单词",Size=new Size(32,32)};var star=new RogueIcon{Kind="star",AccessibleName="收藏单词",Size=new Size(32,32)};foreach(Control c in new Control[]{progress,title,status,word,pronunciation,meaning,input,hear,star})parent.Controls.Add(c);tips.SetToolTip(hear,"朗读单词");tips.SetToolTip(star,"收藏到生词本");hear.Click+=(o,e)=>{if(s.wordQuestion!=null)SpeakWord(s.wordQuestion.entry.word);};star.Click+=(o,e)=>{if(s.wordQuestion!=null)ToggleRogueFavorite(s.wordQuestion.entry,star);};
  var optionSummary=new HallPagedText{Font=GameTheme.Body(11),Visible=false};parent.Controls.Add(optionSummary);var buttons=new VNButton[4];answer=choice=>{if(s.guidanceFeedback!=null)return;var q=s.wordQuestion;if(q==null||q.kind<0)return;bool ok=ExpeditionVocabulary.Correct(q,choice,input.Text);q.answered=true;q.spellingDraft=input.Text;int mastery=ExpeditionVocabulary.Progress(save.rogue,q.entry.word,DateTime.Today).stage;bool effective=TavernHall.WordResearch(s,q.entry.word,mastery,ok);s.guidanceCount++;if(ok)s.guidanceCorrect++;s.guidanceFeedback=(ok?"回答正确":"回答错误")+"\n"+(s.freeStudy?"自由巩固完成 · 保留原复习日期":ExpeditionVocabulary.Answer(save.rogue,q,ok,DateTime.Today));if(s.freeStudy)ExpeditionVocabulary.Profile(save.rogue).serial++;if(s.guidanceCount%3==0){s.guidanceFeedback+="\n三题反馈：正确 "+s.guidanceCorrect+" / 3\n"+("现场指导 "+s.boosts+" / 3 · 研修 "+s.research+" / 100 · 待选奖励 "+s.rewards);s.guidanceCorrect=0;}s.guidanceFeedback+=effective?"\n有效学习 +5 研修进度":"\n本阶段奖励已记录，可继续巩固或学习新词。";Persist();refresh();};
  for(int i=0;i<4;i++){int choice=i;buttons[i]=PartyButton("",()=>answer(choice),200,44);buttons[i].Font=GameTheme.Body(11);parent.Controls.Add(buttons[i]);}
  var next=PartyButton("下一题",()=>{if(s.guidanceFeedback==null&&s.wordQuestion!=null&&s.wordQuestion.kind==3){answer(-1);return;}if(s.guidanceFeedback==null&&s.wordQuestion!=null&&s.wordQuestion.kind>=0)return;s.guidanceSerial++;s.wordQuestion=null;s.guidanceFeedback=null;input.Text="";refresh();Persist();},180,40);parent.Controls.Add(next);hallGuidanceEnter=()=>{if(parent.IsDisposed||!parent.Visible||s.guidanceFeedback==null||!next.Visible)return false;next.PerformClick();return true;};next.KeyDown+=(o,e)=>{if(e.KeyCode==Keys.Enter){e.Handled=e.SuppressKeyPress=true;next.PerformClick();}};
  layout=()=>{
   int w=Math.Max(100,parent.ClientSize.Width-16),h=parent.ClientSize.Height,y=4;bool compact=h<440,feedback=s.guidanceFeedback!=null;
   progress.Bounds=new Rectangle(8,y,w,60);y+=64;title.Bounds=new Rectangle(8,y,w,26);y+=30;
   status.Visible=!compact||!feedback;if(status.Visible){int sh=compact?28:Math.Min(76,Math.Max(28,TextRenderer.MeasureText(status.Text,status.Font,new Size(w-8,10000),TextFormatFlags.WordBreak|TextFormatFlags.NoPadding).Height+8));status.Bounds=new Rectangle(8,y,w,sh);y+=sh+4;}
   int wh=compact?40:48;int wordWidth=Math.Min(w-74,TextRenderer.MeasureText(word.Text,word.Font,Size.Empty,TextFormatFlags.NoPadding|TextFormatFlags.SingleLine).Width+6);word.Bounds=new Rectangle(8,y,Math.Max(20,wordWidth),wh);hear.Size=star.Size=new Size(compact?28:32,compact?28:32);hear.Location=new Point(word.Right,y+4);star.Location=new Point(hear.Visible?hear.Right:word.Right,y+4);y+=wh+4;
   bool inline=pronunciation.Visible&&star.Right+8+TextRenderer.MeasureText(pronunciation.Text,pronunciation.Font).Width<8+w;if(inline){pronunciation.Bounds=new Rectangle(star.Right+8,word.Top,w-(star.Right+8),wh);}else if(pronunciation.Visible){pronunciation.Bounds=new Rectangle(8,y,w,22);y+=26;}
   int bottom=h-8;if(next.Visible){next.Bounds=new Rectangle(8+Math.Max(0,w-180),bottom-36,Math.Min(w,180),36);bottom-=42;}
   if(meaning.Visible){meaning.Content=(compact?s.guidanceFeedback+"\n\n":"")+VocabularySettlementDetails(s.wordQuestion.entry);meaning.Bounds=new Rectangle(8,y,w,Math.Max(50,bottom-y));}
   if(input.Visible)input.Bounds=new Rectangle(8,y,w,34);
   optionSummary.Visible=compact&&buttons[0].Visible;
   if(buttons[0].Visible){if(compact){int buttonY=bottom-32;optionSummary.Content=String.Join("\n",Enumerable.Range(0,s.wordQuestion.options.Count).Select(i=>((char)('A'+i))+". "+s.wordQuestion.options[i]));optionSummary.Bounds=new Rectangle(8,y,w,Math.Max(48,buttonY-y-6));for(int i=0;i<4;i++){buttons[i].Text=((char)('A'+i)).ToString();buttons[i].Bounds=new Rectangle(8+i*w/4,buttonY,w/4-4,32);}}
    else{int bw=(w-8)/2,bh=Math.Max(46,(bottom-y-8)/2);for(int i=0;i<4;i++){buttons[i].Text=i<s.wordQuestion.options.Count?((char)('A'+i))+". "+s.wordQuestion.options[i]:"";buttons[i].Bounds=new Rectangle(8+(i%2)*(bw+8),y+(i/2)*(bh+8),bw,bh);}}}
  };
  refresh=()=>{if(s.wordQuestion==null){bool free;s.wordQuestion=TavernHall.PracticeQuestion(save.rogue,VocabularyBank(mode),DateTime.Today,out free);s.freeStudy=free;}var q=s.wordQuestion;bool feedback=s.guidanceFeedback!=null,available=q.kind>=0,spelling=q.kind==3;progress.Content=VocabularyProgressText(mode).Replace(" · 学习中","\n学习中");title.Text=feedback?"指导结算":"英语指导 · "+(s.guidanceCount%3+1)+" / 3";status.Text=feedback?s.guidanceFeedback:available?(s.freeStudy?"自由巩固 · 保留到期复习安排":ExpeditionVocabulary.Status(save.rogue,q,DateTime.Today)):"今日暂无待学词汇，可返回英语指导选择词库或继续营业。";status.ForeColor=feedback?(s.guidanceFeedback.StartsWith("回答正确")?Color.FromArgb(112,225,155):Color.FromArgb(249,151,126)):GuildChrome.Ivory;word.Text=!available?"":feedback||q.kind==0?q.entry.word:StudyPromptMeaning(q.entry);word.Font=feedback||q.kind==0?GameTheme.Latin(21):GameTheme.Body(15);word.Visible=available;pronunciation.Text=available&&(feedback||q.kind==0)?WordPhonetic(q.entry.word):"";pronunciation.Visible=pronunciation.Text.Length>0;hear.Visible=available&&(feedback||q.kind==0||spelling);star.Visible=available;star.Selected=available&&save.words.Any(v=>v.text.Equals(q.entry.word,StringComparison.OrdinalIgnoreCase));meaning.Visible=feedback&&available;meaning.Content=meaning.Visible?VocabularySettlementDetails(q.entry):"";input.Visible=spelling&&!feedback;for(int i=0;i<4;i++){buttons[i].Visible=available&&!spelling&&!feedback;buttons[i].Text=i<q.options.Count?((char)('A'+i))+". "+q.options[i]:"";}next.Visible=feedback||spelling||!available;next.Text=feedback?"继续 · Enter":spelling?"提交拼写":"刷新到期复习";if(!feedback&&spelling)input.Text=q.spellingDraft??"";layout();if(feedback)next.Focus();};input.TextChanged+=(o,e)=>{if(s.wordQuestion!=null)s.wordQuestion.spellingDraft=input.Text;};input.KeyDown+=(o,e)=>{if(e.KeyCode==Keys.Enter){e.Handled=e.SuppressKeyPress=true;next.PerformClick();}};parent.Resize+=(o,e)=>{if(!word.IsDisposed)layout();};hallSaveStudy=()=>{};refresh();}
 string EmployeeText(HallEmployee e,bool chef){return e.name+" · "+(chef?"厨师 · 特长：细心":"服务员 · 特长：健谈")+" Lv."+e.level+"\n手艺 "+e.Craft+" · 效率 "+e.Efficiency+" · 服务 "+e.Service+" · 体力 "+e.Stamina+"\n成长 "+e.xp+" / "+(e.level==5?"满级":e.NextXp.ToString())+" · 工作贡献 "+e.workXp+" / 研修贡献 "+e.listeningXp+" / 心得贡献 "+e.itemXp+"\n疲劳 "+(int)e.fatigue+" · "+e.action+"\n三级："+(chef?"双份切配（需双锅）":"双盘送餐")+" · 五级："+(chef?"拿手料理（品质+3）":"熟练服务（小费提升）");}
}
